#!/usr/bin/env bash
# Exercise the binding gate's inventory and failure handling without installing
# protoc. The stub only supplies known generated bytes; the real generation
# check runs separately with the pinned compiler in export acceptance.
set -euo pipefail
repo_root="$(git rev-parse --show-toplevel)"
work_dir="$(mktemp -d "${TMPDIR:-/tmp}/ptah-provider-protocol-selftest.XXXXXX")"
trap 'rm -rf "$work_dir"' EXIT
mkdir -p "$work_dir/repo/provider-sdk/protocol/experimental" "$work_dir/bin"
cp "$repo_root/scripts/check-provider-protocol.sh" "$work_dir/repo/check.sh"
git -C "$work_dir/repo" init --quiet
cat > "$work_dir/bin/protoc" <<'STUB'
#!/usr/bin/env bash
set -euo pipefail
if [[ -f fail-generator ]]; then
  printf 'deliberate generator failure\n' >&2
  exit 23
fi
output=''
for argument in "$@"; do
  case "$argument" in --go_out=*) output="${argument#--go_out=}" ;; esac
done
[[ -n "$output" ]]
mkdir -p "$output/protocol/experimental"
printf 'message binding\n' > "$output/protocol/experimental/provider.pb.go"
printf 'service binding\n' > "$output/protocol/experimental/provider_grpc.pb.go"
STUB
chmod +x "$work_dir/bin/protoc"
export PATH="$work_dir/bin:$PATH"
cd "$work_dir/repo"
source_path='provider-sdk/protocol/experimental/provider.proto'
message_path='provider-sdk/protocol/experimental/provider.pb.go'
service_path='provider-sdk/protocol/experimental/provider_grpc.pb.go'
printf 'syntax = "proto3";\n' > "$source_path"
printf 'message binding\n' > "$message_path"
printf 'service binding\n' > "$service_path"
git add provider-sdk

accept() {
  if ! bash check.sh > "$work_dir/output" 2>&1; then
    cat "$work_dir/output" >&2
    printf 'provider protocol self-test: refused %s\n' "$1" >&2
    exit 1
  fi
}
reject() {
  if bash check.sh > "$work_dir/output" 2>&1; then
    printf 'provider protocol self-test: accepted %s\n' "$1" >&2
    exit 1
  fi
  if ! grep -qF "$2" "$work_dir/output"; then
    cat "$work_dir/output" >&2
    printf 'provider protocol self-test: wrong refusal for %s\n' "$1" >&2
    exit 1
  fi
}
accept 'matching tracked bindings'
printf 'untracked source\n' > provider-sdk/protocol/experimental/untracked.proto
accept 'an untracked source outside the inventory'
printf 'stale binding\n' > "$message_path"
reject 'stale generated bytes' 'binding differs from generated output'
printf 'message binding\n' > "$message_path"
accept 'repaired generated bytes'
touch fail-generator
reject 'generator failure before writing output' 'deliberate generator failure'
rm fail-generator
accept 'repaired generator'
git rm --cached --quiet "$service_path"
reject 'missing tracked binding' 'binding inventory is incomplete'
git add "$service_path"
accept 'restored binding inventory'
git rm --cached --quiet "$source_path"
reject 'empty protocol inventory' 'protocol inventory is empty'
git add "$source_path"
accept 'restored source inventory'
printf 'Provider protocol gate self-test passed.\n'
